        def _value_matches_type(value: Any, ptype: str) -> bool:
            if ptype == "bool":
                return isinstance(value, bool)
            if ptype == "int":
                return isinstance(value, int) and not isinstance(value, bool)
            if ptype == "float":
                return isinstance(value, (int, float)) and not isinstance(value, bool)
            if ptype in ("string", "enum"):
                return isinstance(value, str)
            return False

        layer_rank = {name: i for i, name in enumerate(LAYER_ORDER)}
        files = [("universal", "universal", REGISTRY_DIR / "universal.toml")]
        files.extend((f"domain/{p.stem}", "domain", p) for p in sorted((REGISTRY_DIR / "domains").glob("*.toml")))
        files.extend((f"task/{p.stem}", "task", p) for p in sorted((REGISTRY_DIR / "tasks").glob("*.toml")))
        files.extend((f"model/{p.stem}", "model", p) for p in sorted((REGISTRY_DIR / "models").glob("*.toml")))

        for name, layer, path in files:
